				"nav": "Пресеты агента",
				"sectionIntro": "Выберите инструменты агента и то, как он работает. Для повседневных задач — режим «Стандартный», для расширения возможностей DSH — режим «Создатель».",
				"setDefault": "Сделать пресетом новых задач по умолчанию",
