				"presetCordisName": "Режим Creator",
				"presetCordisDescription": "Настройка DSH через диалог. Позвольте агенту написать плагины, добавляющие возможности или интерфейс, либо собрать собственный режим из инструментов и промптов.",
				"inUse": "По умолчанию для новых задач",
