				"settings.goalVerificationHint": "Включено по умолчанию: задача, выполненная в форме цели, должна пройти приёмку, прежде чем update_goal сможет отметить её выполненной (три критерия качества кода для инженерных задач, порог 0,65, два раунда на критерий с переменой мест A/B, и работа должна обойти базовую линию пустой работы). Первый провал возвращает исправляющему агенту итоговый балл, оценки по критериям и найденные замечания, и одно выполнение может быть принято максимум дважды; второй провал завершает выполнение неудачей. Это влияет только на выполнения доски в форме цели и никогда — на обычный чат или задачу с выключенным флагом запуска через /goal. Каждая приёмка действительно обращается к модели-судье и расходует квоту.",
